 if(state.step===2)b='<div class="form-section"><div class="section-title"><h2>确认产品基本信息</h2>'+badge('待人工确认','warning')+'</div><p class="page-subtitle" style="margin-bottom:18px">以下信息会写入当前任务，后续审核仅围绕一个产品型号执行。</p><div class="form-grid"><div class="field full"><label for="create-customer-name">客户名称 <span class="required">*</span></label><input class="control" id="create-customer-name" value="'+esc(draft.customer_name||'')+'" required></div><div class="field"><label for="create-product-name">产品名称 <span class="required">*</span></label><input class="control" id="create-product-name" value="'+esc(draft.product_name||'')+'" required></div><div class="field"><label for="create-product-model">产品型号 <span class="required">*</span></label><input class="control" id="create-product-model" value="'+esc(draft.product_model||'')+'" required></div></div></div>'+error+'<div class="form-footer"><button class="btn btn-secondary" data-act="prev" '+(state.createBusy?'disabled':'')+'>上一步</button><button class="btn btn-primary" data-act="next" '+(state.createBusy?'disabled':'')+'>确认并继续 '+I('next')+'</button></div>';
