 const task=state.detailTask;const status=taskStatus(task.status);const currentRound=(task.rounds||[]).find(round=>round.id===task.current_round_id)||(task.rounds||[]).slice(-1)[0];const standardsList=currentRound?.standards||[];const issueCount=(task.issues||[]).length;const tabs=[['overview','概览'],['files','文件'],['standards','适用标准'],['review','审核结果'],['rounds','审核轮次'],['report','报告'],['logs','操作记录']];let content='';
