 if(state.tab==='files')content='<div class="section-title"><div><h2>任务文件</h2><p class="page-subtitle">文件按任务归档，并挂接到当前审核轮次。</p></div><button class="btn btn-primary btn-sm" data-act="detail-upload">'+I('upload')+'补充文件</button></div>'+taskFiles(task.files||[]);
 if(state.tab==='standards')content='<div class="section-title"><div><h2>本轮适用标准</h2><p class="page-subtitle">审核使用的标准版本将在确认后形成轮次快照。</p></div><button class="btn btn-secondary btn-sm" data-act="add-standard">'+I('plus')+'添加标准</button></div>'+(standardsList.length?'<div class="panel">'+standardsList.map(item=>'<div class="standard-row"><span class="file-icon">'+I('book')+'</span><div><div class="standard-name mono">'+esc(item.standard_code||item.full_code||'未命名标准')+'</div><div>'+esc(item.standard_name||'')+'</div></div>'+badge('已选择','success')+'</div>').join('')+'</div>':'<div class="panel"><div class="empty-state compact-empty"><div><span class="empty-icon">'+I('book')+'</span><h2>本轮尚未选择标准</h2><button class="btn btn-primary" data-act="add-standard">'+I('plus')+'添加标准</button></div></div></div>');
