 if(state.tab==='report'||state.tab==='logs')content='<div class="empty-state"><div><span class="empty-icon">'+I(state.tab==='report'?'archive':'info')+'</span><h2>'+(state.tab==='report'?'本轮尚未生成报告':'暂无可显示的操作记录')+'</h2></div></div>';
