 return shell(hero+'<div class="detail-tabs"><div class="tabs">'+tabs.map(item=>'<button class="tab '+(state.tab===item[0]?'active':'')+'" data-tab="'+item[0]+'">'+item[1]+(item[0]==='review'&&issueCount?'<span class="tab-count">'+issueCount+'</span>':'')+'</button>').join('')+'</div></div><div class="detail-content">'+content+'</div>','tasks')
