function review(){const s=issues[state.issue];const queue=issues.map((x,i)=>'<div class="issue-card '+(i===state.issue?'active':'')+'" data-issue="'+i+'"><div class="issue-head"><span class="issue-code mono">#'+String(i+1).padStart(2,'0')+' · '+x[2]+'</span>'+sev(x[1])+'</div><h3>'+x[0]+'</h3><p>'+x[5]+'</p><div class="issue-foot"><span>'+x[3]+' · P'+x[4]+'</span><span>置信度 '+(98-i*5)+'%</span></div></div>').join('');return shell('<div class="review-shell"><div class="review-topbar"><button class="icon-btn" data-act="leave">'+I('back')+'</button><div class="review-title"><strong>'+s[0]+'</strong><span class="mono">SH-2026-000128 · 第 2 轮</span></div><div class="review-progress"><span>已复核 3 / 11</span><div class="progress-track"><div class="progress-bar" style="width:27%"></div></div></div><button class="btn btn-primary btn-sm" data-act="finish">完成本轮复核</button></div><div class="review-workspace"><section class="review-column"><div class="review-col-head"><strong>问题队列</strong>'+I('filter')+'</div><div class="review-filters"><button class="filter-pill active">全部 8</button><button class="filter-pill">严重 2</button><button class="filter-pill">一般 3</button></div><div class="issue-queue">'+queue+'</div></section><section class="review-column"><div class="document-toolbar"><select class="doc-select"><option>'+s[3]+'</option></select><span class="page-indicator">第 '+s[4]+' / 46 页</span></div><div class="document-canvas"><article class="paper"><div class="paper-head"><h2>DSJ80/40/2×75 带式输送机</h2><p>产品使用说明书</p></div><h3>4. 主要技术参数</h3><p>本产品适用于煤矿井下巷道连续运输散状物料。</p><table class="paper-table"><tr><th>项目</th><th>技术参数</th><th>单位</th></tr><tr><td>带宽</td><td>800</td><td>mm</td></tr><tr><td>输送能力</td><td>400</td><td>t/h</td></tr><tr class="evidence-highlight"><td>驱动电机功率</td><td><strong>2 × 55</strong></td><td>kW</td></tr><tr><td>带速</td><td>2.0</td><td>m/s</td></tr></table><h3>5. 结构与工作原理</h3><p>输送机由机头驱动部、储带装置、张紧装置、中间架、机尾和电气控制系统组成。</p></article></div></section><aside class="review-column"><div class="review-col-head"><strong>依据与人工结论</strong>'+I('more')+'</div><div class="evidence-panel"><div class="evidence-section"><h3>客户证据</h3><div class="evidence-box"><strong>'+s[3]+' · 第 '+s[4]+' 页</strong><div class="quote">'+s[5]+'</div></div></div><div class="evidence-section"><h3>标准依据</h3><div class="evidence-box"><strong class="mono">MT/T 820-2023 · 5.3.2</strong><div class="quote">驱动装置额定功率应满足设计输送能力，并与产品型号标示一致。</div></div></div><div class="evidence-section"><h3>系统判断</h3><div class="ai-note">'+I('wand')+'<span>型号中的“2×75”表示双电机额定功率各为 75 kW，说明书参数与图纸不一致。</span></div></div><div class="evidence-section"><div class="field"><label>问题描述</label><textarea class="control">'+s[5]+'</textarea></div><div class="form-grid"><div class="field"><label>分类</label><select class="control"><option>'+s[2]+'</option></select></div><div class="field"><label>等级</label><select class="control"><option>'+s[1]+'</option></select></div></div></div></div><div class="review-actions"><button class="btn btn-danger" data-act="reject">'+I('close')+'驳回问题</button><button class="btn btn-primary" data-act="confirm">'+I('check')+'确认问题</button></div></aside></div></div>','tasks')}
function standardList(){if(state.standardsLoading)return shell(head('知识依据','标准库','正在读取标准主档和版本。')+'<div class="panel"><div class="panel-loading">正在加载标准库...</div></div>','standards');const rows=state.standards.map(item=>{const version=(item.versions||[])[0];const status=standardStatus(item.status||version?.status);return {id:item.id,code:item.standard_code,name:item.standard_name,type:item.standard_type,version:version?.version_label||'未建版本',fullCode:version?.full_code||'暂无版本',status}});return shell(head('知识依据','标准库','统一管理标准主档、版本、解析修订和任务引用。','<button class="btn btn-secondary">'+I('task')+'解析队列</button><button class="btn btn-primary" data-act="upload-standard">'+I('upload')+'上传标准</button>')+'<div class="toolbar"><div class="search">'+I('search')+'<input class="control" placeholder="搜索标准编号、名称或条款内容"></div><select class="control"><option>全部类型</option></select><select class="control hide-mobile"><option>全部状态</option></select></div><div class="table-shell"><div class="table-wrap"><table class="data-table"><thead><tr><th>标准编号</th><th>标准名称</th><th>版本</th><th>类型</th><th>状态</th><th>版本数</th><th></th></tr></thead><tbody>'+rows.map(item=>'<tr data-act="standard-detail" data-standard-id="'+esc(item.id)+'"><td class="mono">'+esc(item.code)+'</td><td><span class="cell-main">'+esc(item.name)+'</span></td><td class="mono">'+esc(item.fullCode)+'</td><td>'+esc(item.type)+'</td><td>'+badge(esc(item.status[0]),item.status[1])+'</td><td>'+((state.standards.find(x=>x.id===item.id)?.versions||[]).length)+'</td><td>'+I('more')+'</td></tr>').join('')+'</tbody></table></div><div class="table-footer"><span>共 '+rows.length+' 项标准</span><div class="pagination"><button class="page-btn active">1</button></div></div></div>','standards')}
function standardDetail(){if(state.standardDetailLoading)return shell(head('知识依据','标准详情','正在读取标准版本和条款。')+'<div class="panel"><div class="panel-loading">正在加载标准详情...</div></div>','standards');if(!state.standardDetail)return shell(head('知识依据','标准详情','从标准库选择一个标准。')+'<div class="panel"><div class="empty-state"><div><span class="empty-icon">'+I('book')+'</span><h2>标准详情加载失败</h2><p>'+esc(state.standardDetailError||'请选择标准库中的一项标准。')+'</p><button class="btn btn-primary" data-nav="standards">返回标准库</button></div></div></div>','standards');const item=state.standardDetail;const version=(item.versions||[])[0];const status=standardStatus(version?.status||item.status);const clauses=version?.latest_parse_revision?.clauses||[];return shell('<div class="breadcrumb"><button data-nav="standards">标准库</button>'+I('next')+'<span class="mono">'+esc(item.standard_code)+'</span></div>'+head(item.standard_type+' · '+status[0],item.standard_name,version?('版本 '+version.full_code+'，发布于 '+(version.publish_date||'暂无')+'，实施于 '+(version.implement_date||'暂无')+'.'):'尚未创建标准版本。','<button class="btn btn-secondary" data-act="compare">版本比较</button><button class="btn btn-primary" data-act="edit-standard">'+I('edit')+'编辑校对</button>')+'<div class="split-editor"><aside class="editor-list"><div class="editor-list-head"><strong>版本列表</strong></div>'+(item.versions||[]).map((versionItem,index)=>'<div class="list-entry '+(!index?'active':'')+'"><strong class="mono">'+esc(versionItem.full_code)+'</strong><span>'+esc(standardStatus(versionItem.status)[0])+'</span></div>').join('')+'</aside><section class="editor-main"><div class="editor-head"><strong>'+esc(version?.latest_parse_revision?.revision_no||'暂无解析修订')+' · 条款结构化预览</strong>'+badge(esc(version?.latest_parse_revision?.status==='published'?'已发布':'待校对'),version?.latest_parse_revision?.status==='published'?'success':'warning')+'</div><div class="editor-body"><div class="facts"><div class="fact"><div class="fact-label">标准编号</div><div class="fact-value mono">'+esc(version?.full_code||item.standard_code)+'</div></div><div class="fact"><div class="fact-label">解析修订</div><div class="fact-value">'+esc(version?.latest_parse_revision?.revision_no||'暂无')+'</div></div><div class="fact"><div class="fact-label">条款数量</div><div class="fact-value">'+clauses.length+'</div></div></div><h2 style="margin-top:22px">条款列表</h2>'+(clauses.length?'<div class="clause-tree">'+clauses.map((clause,index)=>'<div class="clause '+(!index?'active':'')+'"><span class="clause-code">'+esc(clause.clause_code)+'</span><span>'+esc(clause.title||clause.original_text)+'</span><span class="clause-state">'+esc(clause.proof_status||'待确认')+'</span></div>').join('')+'</div>':'<div class="empty-state compact-empty"><div><h2>暂无结构化条款</h2><p>请完成解析修订后再发布版本。</p></div></div>')+'</div></section></div>','standards')}
function ruleStatus(status){return ({published:['已发布','success'],draft:['草稿','neutral'],testing:['测试中','warning'],paused:['已暂停','warning'],archived:['已归档','neutral']})[status]||[status||'未知','neutral']}
function rulesFromApi(){if(state.rulesLoading)return shell(head('判断方法','审核规则','正在读取规则主档、版本和执行器目录。')+'<div class="panel"><div class="panel-loading">正在加载审核规则...</div></div>','rules');if(state.ruleCatalogError)return shell(head('判断方法','审核规则','规则目录暂时不可用。')+'<div class="panel"><div class="empty-state compact-empty"><div><h2>规则目录加载失败</h2><p>'+esc(state.ruleCatalogError)+'</p><button class="btn btn-primary" data-nav="workbench">返回工作台</button></div></div></div>','rules');const rows=state.rulesCatalog.map(item=>{const version=(item.versions||[])[0];const executor=state.executors.find(candidate=>candidate.executor_code===item.executor_code);const status=ruleStatus(version?.status||item.status);return {id:item.id,code:item.rule_code,name:item.rule_name,executor:item.executor_code||executor?.executor_code||'未绑定',severity:item.default_severity||item.severity||'提示',version:version?.version_no||'暂无版本',status}});const published=rows.filter(item=>item.status[0]==='已发布').length;return shell(head('判断方法','审核规则','规则主档与版本来自数据库，执行器代码由研发随 Worker 发布。','<button class="btn btn-secondary" data-act="test-rule">'+I('play')+'试运行</button><button class="btn btn-primary" data-act="edit-rule">'+I('plus')+'新建规则</button>')+'<div class="rule-layout"><div><div class="toolbar"><div class="search">'+I('search')+'<input class="control" placeholder="搜索规则名称或编码"></div><select class="control"><option>全部规则类型</option></select></div><div class="table-shell"><div class="table-wrap"><table class="data-table"><thead><tr><th>规则</th><th>执行器</th><th>等级</th><th>版本</th><th>状态</th><th></th></tr></thead><tbody>'+rows.map(item=>'<tr data-act="edit-rule"><td><span class="cell-main">'+esc(item.name)+'</span><span class="cell-sub mono">'+esc(item.code)+'</span></td><td class="mono">'+esc(item.executor)+'</td><td>'+sev(esc(item.severity))+'</td><td>'+esc(item.version)+'</td><td>'+badge(esc(item.status[0]),item.status[1])+'</td><td>'+I('more')+'</td></tr>').join('')+'</tbody></table></div><div class="table-footer"><span>共 '+rows.length+' 项规则</span><span>'+published+' 项已发布</span></div></div></div><aside class="panel rule-side"><div class="panel-head"><h2>目录概况</h2></div><div class="panel-body"><div class="summary-block"><div class="summary-row"><span>规则主档</span><strong>'+rows.length+'</strong></div><div class="summary-row"><span>已发布规则</span><strong>'+published+'</strong></div><div class="summary-row"><span>执行器目录</span><strong>'+state.executors.length+'</strong></div><div class="summary-row"><span>待配置版本</span><strong>'+rows.filter(item=>item.status[0]==='草稿').length+'</strong></div></div><h3 style="margin-top:20px">当前执行器</h3><div class="code-box">'+(state.executors[0]?esc(state.executors[0].executor_code)+'<br><br>'+esc(state.executors[0].executor_name):'暂无执行器')+'</div></div></aside></div>','rules')}
function rules(){const r=[['受控件安标证剩余有效期','CONTROLLED_PART_CERT_VALIDITY','date_validity','一般'],['产品型号跨文件一致性','PRODUCT_MODEL_CONSISTENCY','normalized_compare','严重'],['引用标准有效性检查','STANDARD_VERSION_STATUS','standard_status','一般'],['AI 判断必须具备标准依据','AI_EVIDENCE_REQUIRED','evidence_required','提示']];return shell(head('判断方法','审核规则','基于预置执行器配置确定性检查，并管理 AI 审核策略。','<button class="btn btn-secondary" data-act="test-rule">'+I('play')+'试运行</button><button class="btn btn-primary" data-act="edit-rule">'+I('plus')+'新建规则</button>')+'<div class="rule-layout"><div><div class="toolbar"><div class="search">'+I('search')+'<input class="control" placeholder="搜索规则名称或编码"></div><select class="control"><option>全部规则类型</option></select></div><div class="table-shell"><div class="table-wrap"><table class="data-table"><thead><tr><th>规则</th><th>执行器</th><th>等级</th><th>版本</th><th>启用</th><th></th></tr></thead><tbody>'+r.map(x=>'<tr data-act="edit-rule"><td><span class="cell-main">'+x[0]+'</span><span class="cell-sub mono">'+x[1]+'</span></td><td class="mono">'+x[2]+'</td><td>'+sev(x[3])+'</td><td>v1.3</td><td><label class="switch"><input type="checkbox" checked><span class="switch-track"></span></label></td><td>'+I('more')+'</td></tr>').join('')+'</tbody></table></div></div></div><aside class="panel rule-side"><div class="panel-head"><h2>规则概况</h2></div><div class="panel-body"><div class="summary-block"><div class="summary-row"><span>已发布规则</span><strong>27</strong></div><div class="summary-row"><span>本月命中</span><strong>186</strong></div><div class="summary-row"><span>人工确认率</span><strong>87.6%</strong></div><div class="summary-row"><span>人工驳回率</span><strong>6.2%</strong></div></div><h3 style="margin-top:20px">当前执行器</h3><div class="code-box">date_validity<br><br>minimum_remaining_months: 6<br>on_unknown: manual_review</div></div></aside></div>','rules')}
function reports(){const r=[['SH-2026-000116-REP-V1','正式审核报告','煤矿用移动橡套软电缆','MY-0.38/0.66','陕西恒工装备有限公司','通过','success'],['SH-2026-000119-OPN-V2','审核意见单','刮板输送机','SGB620/40T','晋城力拓设备有限公司','不通过','danger'],['SH-2026-000108-REP-V1','正式审核报告','矿用隔爆型高压开关','PJG-630/10','太原中科电气有限公司','通过','success'],['SH-2026-000104-REP-V1','正式审核报告','架空乘人装置','RJY45-25/1200','山西安行装备有限公司','资料不完整无法判断','warning']];return shell(head('成果归档','报告与档案','查看已发布报告及其对应文件、标准、规则和模型快照。','<button class="btn btn-secondary">'+I('download')+'批量导出</button>')+'<div class="toolbar"><div class="search">'+I('search')+'<input class="control" placeholder="搜索报告编号、客户、产品或型号"></div><select class="control"><option>全部报告类型</option></select></div><div class="table-shell"><div class="table-wrap"><table class="data-table"><thead><tr><th>报告编号</th><th>类型</th><th>产品 / 型号</th><th>客户</th><th>结论</th><th>发布时间</th><th></th></tr></thead><tbody>'+r.map(x=>'<tr data-act="report"><td class="mono">'+x[0]+'</td><td>'+x[1]+'</td><td><span class="cell-main">'+x[2]+'</span><span class="cell-sub mono">'+x[3]+'</span></td><td>'+x[4]+'</td><td>'+badge(x[5],x[6])+'</td><td>07-21 11:06</td><td>'+I('eye')+'</td></tr>').join('')+'</tbody></table></div><div class="table-footer"><span>共 93 份已归档报告</span><div class="pagination"><button class="page-btn active">1</button><button class="page-btn">2</button></div></div></div>','reports')}
function report(){return shell('<div class="breadcrumb"><button data-nav="reports">报告与档案</button>'+I('next')+'<span class="mono">SH-2026-000116-REP-V1</span></div>'+head('正式审核报告 · 已发布','报告预览','对应任务 SH-2026-000116，第 1 轮审核。','<button class="btn btn-secondary">打印</button><button class="btn btn-primary" data-act="download">'+I('download')+'下载报告</button>')+'<div class="report-layout"><article class="report-preview"><div class="report-cover"><span class="org">煤矿矿用产品安全审核中心</span><h2>技术文件审核报告</h2><span class="report-no mono">报告编号：SH-2026-000116-REP-V1</span></div><section class="report-section"><h3>一、审核结论</h3><div class="conclusion"><span>经技术文件审核，本次提交资料符合确认依据要求。</span><strong>通过</strong></div></section><section class="report-section"><h3>二、产品信息</h3><div class="facts"><div class="fact"><div class="fact-label">申请企业</div><div class="fact-value">陕西恒工装备有限公司</div></div><div class="fact"><div class="fact-label">产品名称</div><div class="fact-value">煤矿用移动橡套软电缆</div></div><div class="fact"><div class="fact-label">产品型号</div><div class="fact-value mono">MY-0.38/0.66</div></div></div></section><section class="report-section"><h3>三、审核依据</h3><p>GB/T 12972.5-2008《矿用橡套软电缆 第5部分》；MT/T 818.5-2009《煤矿用电缆》。</p></section><section class="report-section"><h3>四、问题及处理情况</h3><table class="paper-table"><tr><th>序号</th><th>问题</th><th>处理结果</th></tr><tr><td>1</td><td>产品型号标识格式不一致</td><td>已修正并确认</td></tr><tr><td>2</td><td>引用标准年代号缺失</td><td>已补充</td></tr></table></section></article><aside class="panel report-side"><div class="panel-head"><h2>报告信息</h2></div><div class="panel-body"><div class="summary-block"><div class="summary-row"><span>报告版本</span><strong>V1</strong></div><div class="summary-row"><span>审核人员</span><strong>王涛</strong></div><div class="summary-row"><span>文件快照</span><strong>5 份</strong></div><div class="summary-row"><span>标准快照</span><strong>4 项</strong></div></div><h3 style="margin-top:20px">下载附件</h3><div class="check-list"><label class="check-row"><input type="checkbox" checked><span>正式审核报告.pdf</span></label><label class="check-row"><input type="checkbox"><span>正式审核报告.docx</span></label><label class="check-row"><input type="checkbox"><span>问题证据截图.zip</span></label></div><button class="btn btn-primary" style="width:100%;margin-top:18px" data-act="download">'+I('download')+'下载所选附件</button></div></aside></div>','reports')}
function settings(){const tabs=['用户管理','模型服务','问题分类','报告模板','系统参数','审计日志'];let b='';if(state.settings==='用户管理')b='<div class="section-title"><div><h2>用户管理</h2><p class="page-subtitle">管理员创建、启用或停用本地账号。</p></div><button class="btn btn-primary btn-sm">'+I('plus')+'创建账号</button></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>用户</th><th>账号</th><th>角色</th><th>状态</th><th>最近登录</th></tr></thead><tbody>'+[['李明','liming','审核人员'],['王涛','wangtao','审核人员'],['陈静','admin','管理员']].map(x=>'<tr><td>'+x[0]+'</td><td class="mono">'+x[1]+'</td><td>'+x[2]+'</td><td>'+badge('已启用','success')+'</td><td>今天 08:56</td></tr>').join('')+'</tbody></table></div></div>';else if(state.settings==='模型服务')b='<div class="section-title"><div><h2>模型服务</h2><p class="page-subtitle">配置外部大模型供应商、主备模型和调用限制。</p></div><button class="btn btn-primary btn-sm">'+I('plus')+'添加供应商</button></div><div class="model-row"><span class="model-logo">QW</span><div><strong>通义千问 · qwen3-vl-plus</strong><div class="cell-sub">主要多模态模型 · API 密钥已配置</div></div>'+badge('连接正常','success')+'</div><div class="model-row"><span class="model-logo">DS</span><div><strong>DeepSeek · deepseek-reasoner</strong><div class="cell-sub">文本推理备用模型 · API 密钥已配置</div></div>'+badge('连接正常','success')+'</div>';else b='<div class="empty-state"><div><span class="empty-icon">'+I('settings')+'</span><h2>'+state.settings+'</h2><p>该模块按第一版设计保留基础维护能力，原型展示其导航与页面结构。</p><button class="btn btn-secondary">进入配置</button></div></div>';return shell(head('平台配置','系统管理','维护用户、模型、分类、模板和系统运行参数。')+'<div class="settings-layout"><nav class="settings-nav">'+tabs.map(x=>'<button class="'+(state.settings===x?'active':'')+'" data-setting="'+x+'">'+x+'</button>').join('')+'</nav><section class="settings-main">'+b+'</section></div>','settings')}
function toast(t){const e=document.createElement('div');e.className='toast';e.innerHTML=I('check')+'<span>'+t+'</span>';document.querySelector('#toast-region').append(e);setTimeout(()=>e.remove(),2600)}
function rulesWithPacks(){const content=rulesFromApi();if(state.rulesLoading||state.ruleCatalogError)return content;const marker='<div class="summary-row"><span>执行器目录</span>';const packRow='<div class="summary-row"><span>规则包</span><strong>'+state.rulePacks.length+'</strong></div>';return content.replace(marker,packRow+marker)}
function go(p){state.page=p;state.modal='';state.drawer=false;location.hash=p;window.scrollTo(0,0);render();if(p==='standards'&&state.auth==='signed_in')loadStandards();if(p==='rules'&&state.auth==='signed_in')loadRules()}
function render(){if(state.auth==='checking'){app.innerHTML=loadingScreen();return}if(state.auth!=='signed_in'){app.innerHTML=loginScreen();return}if(state.page==='settings'&&state.user?.role!=='admin')state.page='workbench';const map={workbench, tasks:taskList, create, detail, review, standards:standardList, standardDetail, rules:rulesWithPacks, reports, report, settings};app.innerHTML=(map[state.page]||workbench)()}
document.addEventListener('click',e=>{
 const n=e.target.closest('[data-nav]');if(n){go(n.dataset.nav);return}
 const t=e.target.closest('[data-tab]');if(t){state.tab=t.dataset.tab;render();return}
 const si=e.target.closest('[data-setting]');if(si){state.settings=si.dataset.setting;render();return}
 const ii=e.target.closest('[data-issue]');if(ii){state.issue=+ii.dataset.issue;render();return}
 const actionNode=e.target.closest('[data-act]');const a=actionNode?.dataset.act;if(!a)return;
 if(a==='logout'){logout();return}
 if(a==='create'){state.step=1;state.uploaded=false;state.pendingFiles=[];state.detailFiles=[];state.createTask=null;state.detailTask=null;state.createError='';go('create');return}
 if(a==='open-task'){loadTaskDetail(actionNode.dataset.taskId||actionNode.closest('[data-task-id]')?.dataset.taskId);return}
 if(a==='next'){if(state.step===1){createDraftAndUpload()}else if(state.step===2){confirmCreateBasicInfo()}else if(state.step===3){confirmCreateStandards()}return}
 if(a==='prev'){state.step=Math.max(1,state.step-1);render();return}
 if(a==='start-audit'){startCreatedAudit();return}
 if(a==='review')go('review');
 if(a==='leave'){state.tab='review';go('detail')}
 if(a==='confirm'||a==='reject'){state.issue=Math.min(issues.length-1,state.issue+1);render();toast(a==='confirm'?'已确认问题并保存人工意见':'已驳回问题，AI 原始结果仍保留')}
 if(a==='finish'){state.modal='finish';render()}
 if(a==='publish'){state.modal='';go('detail');toast('审核意见单正在生成')}
 if(a==='round'){state.modal='round';render()}
 if(a==='confirm-round'){createNextRound();return}
 if(a==='detail-upload'){state.detailFiles=[];state.modal='task-files';render();return}
 if(a==='upload-detail-files'){uploadDetailFiles();return}
 if(a==='remove-file'){const collection=a==='remove-file'&&actionNode.dataset.fileScope==='detail'?state.detailFiles:state.pendingFiles;collection.splice(Number(actionNode.dataset.fileIndex),1);state.uploaded=state.pendingFiles.length>0;render();return}
 if(a==='refresh-task'){loadTaskDetail(state.selectedTaskId,false);return}
 if(a==='add-standard'||a==='upload-standard'){state.modal='standard';render()}
 if(a==='confirm-standard'){state.modal='';render();toast('标准已添加到当前审核轮次')}
 if(a==='standard-detail'){loadStandardDetail(actionNode.dataset.standardId);return}
 if(a==='compare')toast('版本比较：识别到 18 条修改、4 条新增');
 if(a==='edit-standard')toast('条款校对模式已开启');
 if(a==='edit-rule'){state.drawer=true;render()}
 if(a==='test-rule')toast('试运行完成：命中 4 项，结果符合预期');
 if(a==='save-rule'){state.drawer=false;render();toast('规则 v1.4 草稿已保存')}
 if(a==='report')go('report');
 if(a==='download')toast('已生成所选附件，下载即将开始');
 if(a==='close'){state.modal='';state.drawer=false;state.detailFiles=[];render()}
});
document.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();performLogin(e.target)}});
document.addEventListener('change',e=>{if(e.target.id==='task-file-input'){state.pendingFiles=Array.from(e.target.files||[]);state.uploaded=state.pendingFiles.length>0;render()}if(e.target.id==='detail-file-input'){state.detailFiles=Array.from(e.target.files||[]);render()}});
document.addEventListener('input',e=>{if(e.target.id==='task-search')document.querySelectorAll('#task-body tr').forEach(row=>row.style.display=row.textContent.toLowerCase().includes(e.target.value.toLowerCase())?'':'none')});
window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(h&&h!==state.page){state.page=h;render()}});bootstrap();
